-- Fakt kartochkalarining ruscha matni — 13-partiya: Uvaysiy, Nodira, Anbar Otin.
--
-- Uvaysiyning anor haqidagi chistoni (397, 1817) ma'no bo'yicha o'girildi:
-- she'riy qofiya boshqa tilda saqlanmaydi, lekin topishmoqning javobi —
-- anor — bola uchun baribir topiladigan bo'lib qoldi.

-- ===== Uvaysiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Каково настоящее имя Увайси и где она родилась?', fact_ru = 'Я родилась в 1779 году в Маргилане. Моё настоящее имя — Джахан.' WHERE id = 393;
UPDATE fact_cards SET topic_ru = 'Мой наставник', question_ru = 'У кого Увайси училась науке поэзии?', fact_ru = 'Науке поэзии я училась у своего брата Ахунджана-хафиза.' WHERE id = 394;
UPDATE fact_cards SET topic_ru = 'Моё учительство', question_ru = 'Чем занималась Увайси в деле обучения?', fact_ru = 'Выучившись грамоте в семье, я была сперва помощницей учительницы, а затем учительствовала рядом с матерью.' WHERE id = 395;
UPDATE fact_cards SET topic_ru = 'Наставница при дворе', question_ru = 'Кому Увайси была наставницей при кокандском дворе?', fact_ru = 'При кокандском дворе я преподавала поэзию Надире и другим женщинам и была их наставницей.' WHERE id = 396;
UPDATE fact_cards SET topic_ru = 'Мои загадки-чистаны', question_ru = 'Какие стихотворные загадки писала Увайси?', fact_ru = 'Я писала стихотворные загадки — чистаны. Вот самая известная моя загадка: «Что за купол таков: ни двери, ни оконца в нём нет».' WHERE id = 397;
UPDATE fact_cards SET topic_ru = 'Моё творчество', question_ru = 'Сколько газелей написала Увайси?', fact_ru = 'Я написала 269 газелей, 29 мухаммасов, 55 мусаддасов и три дастана.' WHERE id = 398;
UPDATE fact_cards SET topic_ru = 'Мои дастаны', question_ru = 'Как называются дастаны Увайси?', fact_ru = 'Я создала дастаны «Шахзаде Хасан» и «Шахзаде Хусан», а также исторический дастан.' WHERE id = 399;
UPDATE fact_cards SET topic_ru = 'Мои поездки', question_ru = 'По сведениям Дилшод-отин, в каких городах побывала Увайси?', fact_ru = 'По сведениям Дилшод-отин, я побывала в Канибадаме, Худжанде и других городах.' WHERE id = 400;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Где Увайси провела конец своей жизни?', fact_ru = 'В 1842 году, когда Коканд был взят, я вернулась в Маргилан и прожила там до конца своих дней. Я скончалась в 1845 году.' WHERE id = 401;
UPDATE fact_cards SET topic_ru = 'Мой псевдоним', question_ru = '«Увайси» — это настоящее имя поэтессы или литературный псевдоним?', fact_ru = 'Свои стихи я писала под псевдонимом «Увайси». А поскольку настоящее моё имя Джахан, меня называют ещё и Джаханотин.' WHERE id = 1814;
UPDATE fact_cards SET topic_ru = 'Моя семья', question_ru = 'В какой семье выросла Увайси?', fact_ru = 'Мой отец Сиддик был страстно влюблён в поэзию, а мать Чиннибиби была отин и учила девочек. Любовь к стиху передалась мне от семьи.' WHERE id = 1815;
UPDATE fact_cards SET topic_ru = 'Мой диван', question_ru = 'В виде какого собрания сохранились стихи Увайси?', fact_ru = 'Мои стихи собраны в диван. В нём есть газели, мухаммасы, мурабба и чистаны.' WHERE id = 1816;
UPDATE fact_cards SET topic_ru = 'Моя загадка о гранате', question_ru = 'О чём знаменитая загадка Увайси, начинающаяся словами «Что за купол таков...»?', fact_ru = 'Самая знаменитая моя загадка — о гранате. Она начинается словами: «Что за купол таков: ни двери, ни оконца в нём нет» — сумеешь найти отгадку?' WHERE id = 1817;
UPDATE fact_cards SET topic_ru = 'Время моей жизни', question_ru = 'В пору какого ханства жила и творила Увайси?', fact_ru = 'Я жила в пору Кокандского ханства. Правитель того времени Умархан и сам писал стихи под псевдонимом «Амирий».' WHERE id = 1818;
UPDATE fact_cards SET topic_ru = 'Поэтессы-современницы', question_ru = 'Какие поэтессы творили в кокандской литературной среде во времена Увайси?', fact_ru = 'Я творила в одно время с Надирой и Махзуной. Нас знали как поэтесс кокандской литературной среды.' WHERE id = 1819;
UPDATE fact_cards SET topic_ru = 'Память обо мне', question_ru = 'Как сегодня чтят память Увайси в Узбекистане?', fact_ru = 'Сегодня мои стихи вошли в школьные учебники, а в Узбекистане моим именем названы улицы и школы.' WHERE id = 1820;

-- ===== Nodira =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Каково настоящее имя Надиры и кем был её отец?', fact_ru = 'Я родилась в 1792 году в Андижане. Моё настоящее имя — Мохлар-айим, а отцом моим был правитель Андижана Рахманкулбий.' WHERE id = 384;
UPDATE fact_cards SET topic_ru = 'Моё замужество', question_ru = 'За кого вышла замуж Надира?', fact_ru = 'В 1807 году я вышла замуж за правителя Маргилана Умархана.' WHERE id = 385;
UPDATE fact_cards SET topic_ru = 'Как я правила государством', question_ru = 'Кто правил государством после смерти Умархана?', fact_ru = 'После смерти Умархана в 1822 году на престол взошёл мой сын Мухаммад Алихан, но государством по большей части правила я сама.' WHERE id = 386;
UPDATE fact_cards SET topic_ru = 'Моя наставница Увайси', question_ru = 'Какую поэтессу Надира призвала во дворец наставницей?', fact_ru = 'Познакомившись с поэтессой Увайси, я призвала её во дворец наставницей.' WHERE id = 387;
UPDATE fact_cards SET topic_ru = 'Моё созидание', question_ru = 'Какие здания возвела Надира?', fact_ru = 'Я уделяла внимание строительству базаров и торговых рядов, мечетей и медресе, караван-сараев; по моему велению возведены медресе Чалпак и медресе Мохлар-айим.' WHERE id = 388;
UPDATE fact_cards SET topic_ru = 'Мои псевдонимы', question_ru = 'Под какими псевдонимами Надира писала свои стихи?', fact_ru = 'Свои стихи я писала под псевдонимами «Надира», «Комила» и «Макнуна».' WHERE id = 389;
UPDATE fact_cards SET topic_ru = 'Мой диван', question_ru = 'Сколько стихов собрано в диване Надиры?', fact_ru = 'В моём диване собрано 180 стихотворений, написанных под псевдонимом «Надира»: 136 на узбекском языке и 44 на таджикском.' WHERE id = 390;
UPDATE fact_cards SET topic_ru = 'Покровительство поэтессам', question_ru = 'Как Надира относилась к поэтессам при своём дворе?', fact_ru = 'При моём дворе я побуждала поэтесс писать новые произведения.' WHERE id = 391;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'При каких обстоятельствах погибла Надира?', fact_ru = 'В 1842 году, когда бухарский эмир Насрулла вторгся в Коканд, я погибла вместе со своими детьми.' WHERE id = 392;
UPDATE fact_cards SET topic_ru = 'Мой сын на престоле', question_ru = 'Какой сын Надиры сел на кокандский престол после смерти Умархана?', fact_ru = 'После смерти моего супруга Умархана на кокандский престол сел мой сын Мухаммад Алихан. Он был ещё юн, и в государственных делах я ему помогала.' WHERE id = 1744;
UPDATE fact_cards SET topic_ru = 'Мой супруг-поэт', question_ru = 'Под каким псевдонимом писал стихи Умархан, супруг Надиры?', fact_ru = 'Мой супруг Умархан тоже был поэтом: он писал стихи под псевдонимом «Амирий».' WHERE id = 1745;
UPDATE fact_cards SET topic_ru = 'Языки моего творчества', question_ru = 'На каких языках писала свои стихи Надира?', fact_ru = 'Свои стихи я писала на двух языках — узбекском и персидско-таджикском.' WHERE id = 1746;
UPDATE fact_cards SET topic_ru = 'Темы моих стихов', question_ru = 'Какие темы главным образом воспевала Надира в своих стихах?', fact_ru = 'В своих стихах я воспевала любовь, преданность и верность. А в газелях, написанных после смерти Умархана, я излила и сердечную свою печаль.' WHERE id = 1747;
UPDATE fact_cards SET topic_ru = 'Кокандская литературная среда', question_ru = 'Какой город стал крупным литературным центром во времена Надиры?', fact_ru = 'В наше время при кокандском дворе собралось множество поэтов и учёных. Так Коканд стал крупным литературным центром своего времени.' WHERE id = 1748;
UPDATE fact_cards SET topic_ru = 'Моё покровительство книжному искусству', question_ru = 'Что сделала Надира для развития книжного искусства?', fact_ru = 'Я поручала каллиграфам переписывать рукописные книги и украшать их. Так я внесла свой вклад в развитие книжного искусства.' WHERE id = 1749;
UPDATE fact_cards SET topic_ru = 'Память обо мне', question_ru = 'Как чтят память Надиры в Узбекистане?', fact_ru = 'Сегодня в Узбекистане моим именем названы улицы и школы. Мои газели вошли в школьные учебники и звучат в песнях.' WHERE id = 1750;

-- ===== Anbar Otin =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родилась Анбар Отин?', fact_ru = 'Я родилась в 1870 году в Коканде. Моё полное имя — Анбар Отин, дочь Фармонкула.' WHERE id = 301;
UPDATE fact_cards SET topic_ru = 'Моя семья', question_ru = 'Кем были родители Анбар Отин?', fact_ru = 'Мой отец был из последователей поэтессы Увайси, а мать Ашурбиби была дочерью ремесленника.' WHERE id = 302;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'В чьей школе училась Анбар Отин?', fact_ru = 'Я училась в школе Дилшод-отин.' WHERE id = 303;
UPDATE fact_cards SET topic_ru = 'Моё имя «отин»', question_ru = 'Почему Анбар Отин называли «отин»?', fact_ru = 'Оттого что наряду с писанием стихов я давала уроки девочкам своей махалли, меня называли «отин».' WHERE id = 304;
UPDATE fact_cards SET topic_ru = 'Мои языки', question_ru = 'На каких языках творила Анбар Отин?', fact_ru = 'Я творила на узбекском и таджикском языках.' WHERE id = 305;
UPDATE fact_cards SET topic_ru = 'Мой диван', question_ru = 'Сколько газелей собрано в диване Анбар Отин?', fact_ru = 'В 1905 году я составила диван из своих узбекских стихов: в нём 41 газель, 4 мухаммаса, а также кита, маснави и мустазад.' WHERE id = 306;
UPDATE fact_cards SET topic_ru = 'Тема моих стихов', question_ru = 'Какова главная тема стихов Анбар Отин?', fact_ru = 'Большая часть моих стихов на общественные темы: я писала о несправедливости и о положении трудового люда.' WHERE id = 307;
UPDATE fact_cards SET topic_ru = 'Знание и просвещение', question_ru = 'Что возвеличивала Анбар Отин в своих стихах?', fact_ru = 'В своих стихах я возвеличивала знание и просвещение.' WHERE id = 308;
UPDATE fact_cards SET topic_ru = '«Философия чернолюдья»', question_ru = 'О чём произведение Анбар Отин «Философия чернолюдья»?', fact_ru = 'В своём произведении «Философия чернолюдья» я повела речь о тяжком положении женщин.' WHERE id = 309;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умерла Анбар Отин?', fact_ru = 'Я скончалась в 1906 году в Коканде.' WHERE id = 310;
UPDATE fact_cards SET topic_ru = 'Моя наставница Дилшод-отин', question_ru = 'В школе какой поэтессы училась Анбар Отин?', fact_ru = 'Я училась в школе знаменитой кокандской поэтессы Дилшод-отин. Наставница открывала мне тайны поэзии и поддерживала моё дарование.' WHERE id = 1526;
UPDATE fact_cards SET topic_ru = 'Мои любимые поэты', question_ru = 'Чьи произведения любила читать Анбар Отин?', fact_ru = 'Я любила читать произведения Алишера Навои, Физули, Бедиля, Увайси и Надиры. Особенно высоко я ценила творчество Навои.' WHERE id = 1527;
UPDATE fact_cards SET topic_ru = 'Традиция поэтесс', question_ru = 'Традицию каких узбекских поэтесс продолжила Анбар Отин?', fact_ru = 'Я продолжила традицию узбекских поэтесс, начатую Увайси и Надирой. Как и они, я воспевала в стихах боль и мечты женщин.' WHERE id = 1528;
UPDATE fact_cards SET topic_ru = 'Кокандская литературная среда', question_ru = 'Чем в ту пору славился город Коканд, где жила Анбар Отин?', fact_ru = 'Коканд, где я жила, был в ту пору крупным литературным центром. Здесь творили такие поэты, как Мукими и Фуркат, и я тоже возросла в этой среде.' WHERE id = 1529;
UPDATE fact_cards SET topic_ru = 'Родина моего отца', question_ru = 'Откуда был родом Фармонкул, отец Анбар Отин?', fact_ru = 'Мой отец Фармонкул был родом из Маргилана, а позже переехал в Коканд. Я же родилась и выросла в Коканде.' WHERE id = 1530;
UPDATE fact_cards SET topic_ru = 'Мой псевдоним', question_ru = 'Под каким псевдонимом писала свои стихи Анбар Отин?', fact_ru = 'Свои стихи я писала под псевдонимом «Анбар» — под собственным именем.' WHERE id = 1531;
UPDATE fact_cards SET topic_ru = 'Судьба моих стихов сегодня', question_ru = 'Как изучают творчество Анбар Отин в наши дни?', fact_ru = 'Мои рукописи дошли до нас, а стихи изданы в Узбекистане отдельной книгой. Сегодня моё творчество изучают на уроках литературы.' WHERE id = 1532;
